"""Central copy builders for notifications generated by the application."""

from decimal import Decimal


def _money(amount):
    return f"\u20b1{Decimal(str(amount)):,.2f}"


def move_in_payment_notification_copy(*, tenant_name, amount, payment_method, reference):
    """Build a concise move-in confirmation with audit details on separate lines."""
    method = (payment_method or "online").strip()
    normalized_method = method.lower().replace("_", " ").replace("-", " ")
    if normalized_method in {"gcash", "g cash"}:
        payment_sentence = "was successfully received via GCash."
    elif "cash" in normalized_method:
        payment_sentence = "was successfully received as a cash payment."
    elif normalized_method == "paymongo":
        payment_sentence = "was successfully received via PayMongo."
    else:
        payment_sentence = f"was successfully received via {method}."

    separator = "\u00b7"
    missing_reference = "\u2014"
    return (
        "Move-in payment received",
        f"{tenant_name}'s move-in payment of {_money(amount)} {payment_sentence}\n"
        f"Lease activated {separator} First month's bill is paid.\n"
        f"Payment reference: {reference or missing_reference}",
    )


def tenant_account_updated_notification_copy(*, tenant_name, changed_fields):
    """Build account-change copy while keeping the specific action easy to scan."""
    labels = {
        "email": "Email address",
        "username": "Username",
        "role": "Role",
        "password": "Password",
    }
    actions = [labels.get(field, field.replace("_", " ").capitalize()) for field in changed_fields]
    return (
        "Account updated",
        f"An administrator updated {tenant_name}'s account information.\n"
        f"Updated: {', '.join(actions)}",
    )


def payment_submitted_notification_copy(*, tenant_name, amount, method, reference):
    method_label = "GCash" if (method or "").strip().lower() in {"gcash", "g cash"} else (method or "payment")
    return (
        "Payment submitted",
        f"{tenant_name} submitted a payment of {_money(amount)} via {method_label} for review.\n"
        f"Payment reference: {reference}",
    )


def cash_payment_scheduled_notification_copy(*, tenant_name, amount, schedule, reference):
    return (
        "Cash payment requested",
        f"{tenant_name} requested a cash payment of {_money(amount)}.\n"
        f"Preferred time: {schedule or 'To be confirmed'}\n"
        f"Payment reference: {reference}\n"
        "Please confirm the appointment.",
    )


def payment_approved_notification_copy(*, payment_method, amount):
    method_label = (payment_method or "payment").strip()
    if method_label.lower() in {"gcash", "g cash"}:
        method_label = "GCash"
    elif method_label.lower() == "paymongo":
        method_label = "PayMongo"
    elif "cash" in method_label.lower():
        method_label = "cash"
    return (
        "Payment received",
        f"We received your {method_label} payment of {_money(amount)}.\n"
        "Your bill balance has been updated.",
    )


def payment_declined_notification_copy(*, payment_method, amount):
    method_label = (payment_method or "payment").strip()
    if method_label.lower() in {"gcash", "g cash"}:
        method_label = "GCash"
    elif method_label.lower() == "paymongo":
        method_label = "PayMongo"
    elif "cash" in method_label.lower():
        method_label = "cash"
    return (
        "Payment needs attention",
        f"Your {method_label} payment of {_money(amount)} could not be approved.\n"
        "Please contact the administration team or submit a new payment.",
    )


def online_payment_received_notification_copy(*, tenant_name, amount, method, reference):
    method_label = (method or "online").strip()
    if method_label.lower() in {"gcash", "g cash"}:
        method_label = "GCash"
    elif method_label.lower() == "paymongo":
        method_label = "PayMongo"
    reference_label = reference or "\u2014"
    return (
        "Online payment received",
        f"{tenant_name} paid {_money(amount)} via {method_label}.\n"
        f"Payment reference: {reference_label}\n"
        "The selected bills have been marked as paid.",
    )


def cash_appointment_confirmed_notification_copy(*, amount, schedule):
    return (
        "Cash payment appointment confirmed",
        "Your in-person cash payment appointment is confirmed.\n"
        f"Amount: {_money(amount)}\n"
        f"Scheduled: {schedule or 'To be confirmed'}\n"
        "Please bring the exact amount.",
    )


def cash_appointment_rescheduled_notification_copy(*, amount, old_schedule, new_schedule, reference, admin_note=""):
    reference_label = reference or "\u2014"
    lines = [
        "Your in-person cash payment appointment has been rescheduled.",
        f"Previous time: {old_schedule}",
        f"New time: {new_schedule}",
        f"Amount: {_money(amount)}",
        f"Payment reference: {reference_label}",
    ]
    if admin_note:
        lines.append(f"Note from the administration team: {admin_note}")
    return "Cash payment appointment updated", "\n".join(lines)


def maintenance_request_received_notification_copy(*, tenant_name, category, title, unit_number=""):
    unit_text = f" for Unit {unit_number}" if unit_number else ""
    return (
        "Maintenance request received",
        f"Maintenance request: {title}\n"
        f"{tenant_name} sent a {category.lower()} request{unit_text}.",
    )


def maintenance_review_notification_copy(*, review_status, title, unit_number, assigned_staff="", note=""):
    unit_text = f"Unit: {unit_number}"
    if review_status == "ACCEPTED":
        message_lines = [
            f"Your maintenance request, {title}, has been accepted.",
            f"Assigned staff: {assigned_staff or 'To be assigned'}",
            unit_text,
        ]
        title_text = "Maintenance request accepted"
    elif review_status == "REJECTED":
        message_lines = [
            f"Your maintenance request, {title}, could not be approved.",
            unit_text,
            f"Note: {note}" if note else "Contact the administration team if you have questions.",
        ]
        title_text = "Maintenance request update"
    else:
        message_lines = [
            f"Your maintenance request, {title}, is being reviewed again.",
            unit_text,
        ]
        title_text = "Maintenance request under review"
    return title_text, "\n".join(message_lines)


def maintenance_assignment_notification_copy(*, request_id, title, tenant_name, unit_number):
    return (
        "Maintenance request assigned",
        f"You have a new maintenance request to work on.\n"
        f"Maintenance request: {title}\n"
        f"Request number: {request_id}\nTenant: {tenant_name}\nUnit: {unit_number}",
    )


def maintenance_resolved_notification_copy(*, staff_name, request_id, title, tenant_name, unit_number, completed_by):
    return (
        "Maintenance work marked complete",
        f"{staff_name} marked a maintenance request as resolved.\n"
        f"Maintenance request: {title}\nRequest number: {request_id}\n"
        f"Tenant: {tenant_name}\nUnit: {unit_number}\nCompleted by: {completed_by}",
    )


def repair_estimate_notification_copy(*, staff_name, request_id, title, tenant_name, unit_number, amount, is_update=False):
    action = "updated" if is_update else "shared"
    title_text = "Repair estimate updated" if is_update else "Repair estimate received"
    return (
        title_text,
        f"{staff_name} {action} a repair estimate.\n"
        f"Maintenance request: {title}\nRequest number: {request_id}\n"
        f"Tenant: {tenant_name}\nUnit: {unit_number}\nEstimated total: {_money(amount)}",
    )


def maintenance_schedule_notification_copy(*, title, decision, visit_time, unit_number, note=""):
    decision_copy = {
        "approved": "has been confirmed",
        "declined": "could not be scheduled",
        "pending": "is awaiting confirmation",
    }.get((decision or "").lower(), "has been updated")
    lines = [
        f"Your maintenance visit for {title} {decision_copy}.",
        f"Visit time: {visit_time or 'To be confirmed'}",
        f"Unit: {unit_number}",
    ]
    if note:
        lines.append(f"Note: {note}")
    return "Maintenance visit updated", "\n".join(lines)


